  "helpKeepOtpSecure": "OTP सुरक्षित ठेवा: काम सुरू करण्यापूर्वी हा कोड फक्त तुमच्या प्रमाणित कारागिराला सांगा.",
  "helpKeepRecords": "ରେକର୍ଡ ରଖନ୍ତୁ: ଭବିଷ୍ୟତର ସନ୍ଦର୍ଭ ପାଇଁ ଆପଣଙ୍କର ଡିଜିଟାଲ୍ ରସିଦ ଡାଉନଲୋଡ୍ କରନ୍ତୁ।",
  "helpManagerBannerDesc": "ଜିଲ୍ଲା ସ୍ତରୀୟ କାର୍ଯ୍ୟ ପରିଚାଳନା, ସେବା ଆବଣ୍ଟନ ଏବଂ ଗୁଣବତ୍ତା ପରିଚାଳନା ମାର୍ଗଦର୍ଶିକା।",
  "helpManagerEscalationsDesc": "ଗ୍ରାହକ ଅଭିଯୋଗ ଏବଂ ସେବା ସମସ୍ୟାର ଶୀଘ୍ର ସମାଧାନ।",
  "helpManagerEscalationsStep1": "ଦାଖଲ ହୋଇଥିବା ସମସ୍ତ ଅଭିଯୋଗ ଅଗ୍ରାଧିକାର ଭିତ୍ତିରେ ସମୀକ୍ଷା କରନ୍ତୁ।",
  "helpManagerEscalationsStep2": "ମଧ୍ୟସ୍ଥତା ବୈଠକ କରି ଉଭୟ ପକ୍ଷଙ୍କ କଥା ଶୁଣି ନ୍ୟାଯ୍ୟ ସମାଧାନ ଦିଅନ୍ତୁ।",
  "helpManagerEscalationsStep3": "निर्णय लागू करून ग्राहक व कामगार दोघांचे समाधान सुनिश्चित करा.",
  "helpManagerEscalationsTitle": "ଅଭିଯୋଗ ପରିଚାଳନା ଏବଂ ସମାଧାନ",
  "helpManagerOpsDesc": "ଦୈନନ୍ଦିନ ସେବା ଆବଣ୍ଟନ ଏବଂ ଶ୍ରମିକ ଉପଲବ୍ଧତା ପରିଚାଳନା।",
  "helpManagerOpsStep1": "ଜିଲ୍ଲାରେ କାର୍ଯ୍ୟରତ ଶ୍ରମିକଙ୍କ ରିଅଲ୍-ଟାଇମ୍ ଉପଲବ୍ଧତା ଏବଂ କାର୍ଯ୍ୟଭାର ନିରୀକ୍ଷଣ କରନ୍ତୁ।",
  "helpManagerOpsStep2": "ଅଧିକ ଚାହିଦା ଥିବା ଅଞ୍ଚଳରେ ଅତିରିକ୍ତ ଶ୍ରମିକ ଆବଣ୍ଟନ କରନ୍ତୁ।",
