  "helpWorkerAcceptingDesc": "କାମର ଅନୁରୋଧ ପାଆନ୍ତୁ, ଠିକଣା ଦେଖନ୍ତୁ ଏବଂ ତୁରନ୍ତ କାମ ଗ୍ରହଣ କରନ୍ତୁ।",
