  "helpWorkerAcceptingStep3": "'କାମ ଗ୍ରହଣ କରନ୍ତୁ' କ୍ଲିକ୍ କରି ଜିପିଏସ୍ ନେଭିଗେସନ୍ ଆରମ୍ଭ କରନ୍ତୁ।",
