  "workerFlowStep1Desc": "ସକ୍ରିୟ କାର୍ଯ୍ୟ ବିଭାଗରେ ସ୍ଥାନ ଏବଂ ମଜୁରୀ ବିବରଣୀ ଯାଞ୍ଚ କରନ୍ତୁ ଏବଂ ସ୍ୱୀକାର କରନ୍ତୁ ଉପରେ କ୍ଲିକ୍ କରନ୍ତୁ।",
  "workerFlowStep1Title": "କାମ ଗ୍ରହଣ କରନ୍ତୁ:",
  "workerFlowStep2Desc": "ଗ୍ରାହକ ଆପଣଙ୍କ ଆଗମନ ସ୍ଥିତି ଦେଖିବା ପାଇଁ \"ବାଟରେ ଅଛି\" କ୍ଲିକ୍ କରନ୍ତୁ।",
  "workerFlowStep2Title": "କାର୍ଯ୍ୟ ସ୍ଥଳକୁ ଯାଆନ୍ତୁ:",
  "workerFlowStep3Desc": "ଗ୍ରାହକଙ୍କ ଘରେ ପହଞ୍ଚିବା ପରେ, ତାଙ୍କଠାରୁ 4-ଅଙ୍କ ବିଶିଷ୍ଟ କୋଡ୍ ମାଗନ୍ତୁ ଏବଂ କାମ ଆରମ୍ଭ କରନ୍ତୁ।",
  "workerFlowStep3Title": "କାର୍ଯ୍ୟ ଆରମ୍ଭ OTP ପ୍ରବେଶ କରନ୍ତୁ:",
  "workerFlowStep4Desc": "କାମ ସରିବା ପରେ \"ସମ୍ପୂର୍ଣ୍ଣ\" ବୋଲି ଚିହ୍ନିତ କରନ୍ତୁ। ଶୂନ୍ୟ କମିଶନ ସହିତ ସମସ୍ତ ମଜୁରୀ ତୁରନ୍ତ ଆପଣଙ୍କ ଖାତାରେ ଜମା ହେବ।",
  "workerFlowStep4Title": "କାମ ସାରନ୍ତୁ ଏବଂ ତୁରନ୍ତ ପାରିଶ୍ରମିକ ପାଆନ୍ତୁ:",
  "workerFlowStep5Desc": "ଭଲ ରେଟିଂ ବଜାୟ ରଖନ୍ତୁ, ଏକାଡେମୀ ପାଠ୍ୟକ୍ରମ ସମ୍ପୂର୍ଣ୍ଣ କରନ୍ତୁ ଏବଂ ଅଧିକ ଆୟ କରନ୍ତୁ।",
  "workerFlowStep5Title": "ଦକ୍ଷତା ବୃଦ୍ଧି କରନ୍ତୁ:",
  "workerHowItWorksDesc": "ସହକାର କନେକ୍ଟ ୱାର୍କର ପୋର୍ଟାଲ ଆପଣଙ୍କୁ ବିନା କୌଣସି ମଧ୍ୟସ୍ଥିରେ ସିଧାସଳଖ ନିକଟସ୍ଥ ଗ୍ରାହକମାନଙ୍କ ସହିତ ଯୋଡିଥାଏ। ଆପଣ କାର୍ଯ୍ୟ ଅନୁରୋଧ ଗ୍ରହଣ କରିପାରିବେ, ସୁରକ୍ଷିତ OTP ସହିତ କାର୍ଯ୍ୟ ଆରମ୍ଭ କରିପାରିବେ, ତୁରନ୍ତ ନିଜ ଖାତାରେ ମଜୁରୀ ପାଇପାରିବେ ଏବଂ ସାମାଜିକ ସୁରକ୍ଷା ଲାଭ ପାଇପାରିବେ।",
